document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');document.querySelectorAll('[data-country]').forEach(c=>c.hidden=b.dataset.filter!=='All'&&c.dataset.country!==b.dataset.filter)}));
const f=document.getElementById('brief');if(f){let step=0;const panels=[...document.querySelectorAll('.form-step')],next=document.getElementById('next'),back=document.getElementById('back');const q=new URLSearchParams(location.search);for(const n of ['country','city','service'])if(q.has(n))f.elements[n].value=q.get(n);function summary(){return [...new FormData(f)].map(([k,v])=>k.toUpperCase()+': '+v).join('\n')}function show(){panels.forEach((p,i)=>p.hidden=i!==step);back.hidden=step===0;next.textContent=step===2?'Prepare brief ↗':'Continue ↗';document.querySelectorAll('.stepbar span').forEach((x,i)=>x.classList.toggle('done',i<=step));document.getElementById('review').textContent=[f.elements.property.value,f.elements.country.value+' / '+f.elements.city.value,f.elements.service.value].join(' · ')}next.addEventListener('click',()=>{for(const el of panels[step].querySelectorAll('input,select,textarea'))if(!el.reportValidity())return;if(step<2){step++;show()}else{f.hidden=true;document.getElementById('complete').hidden=false}});back.addEventListener('click',()=>{step--;show()});f.addEventListener('submit',e=>e.preventDefault());document.getElementById('download').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob(['CHARLOT CREA — PROJECT BRIEF (PREVIEW)\n\n'+summary()],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='charlot-crea-project-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
